    "source": "tmdb",
    "description": "Серхат — успешный бизнесмен, счастливый муж и прекрасный отец. Он долгие годы был уверен, что ему удалось построить крепкую и любящую семью. Однако совершенно случайно Серхат узнает, что его супруга, с которой он прожил 18 лет вместе и которая родила ему близнецов, на протяжении многих лет изменяла ему. Более того, у нее даже есть маленькая дочь, которую она родила живя в браке с ним. Ситуацию осложняет и тот факт, что в результате трагической случайности Беррак — жена Серхата впадает в кому, а он сам решает начать расследование, которое бы помогло ему узнать всю правду о своей семье.\n\nПоиски приводят мужчину в трущобы Стамбула, где он случайно знакомится с молодой девушкой по имени Зейнеп. Разница в возрасте и социальном статусе не смогла стать преградой для их чувств. Только вот и Серхат, и Зейнеп, понимают, что им будет трудно построить крепкие отношения. К тому же отец девушки, категорически против ее сближения с бизнесменом.",
