    "description": "Ван Линь - молодой человек из деревни, который очень заботится о своей семье. Он живет обычной и спокойной жизнью, помогая своей семье в резьбе по дереву и готовясь к предстоящему экзамену. Но у его семьи есть много долгов перед кланом семьи Ван, и в один момент им приходится отдать все деньги, которые Ван Линю были необходимы для сдачи экзамена.\n\nВ этот момент к ним приходит дядюшка Сы и сообщает о том, что великая секта культивации бессмертия ХэнъЮэ набирает новых учеников, и у молодого Ван Линя появляется шанс изменить свою судьбу.\n\nВан Линь решает воспользоваться этой возможностью, несмотря на протесты своего отца. Несмотря на то, что у него нет особого таланта для культивации и лишь средние способности, ему предстоит проявить невероятную выдержку и мужество, преодолевая многочисленные трудности, тяжелые испытания и собственные недостатки. Все это нужно ему будет пройти, чтобы стать настоящим культиватором бессмертия и самостоятельно написать свою судьбу.",
